UPDATE tb_member_otp
SET attempt_count = attempt_count + 1, updated_at = CURRENT_TIMESTAMP
WHERE otp_id = #{otpId}

UPDATE tb_member_otp
SET verified_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
WHERE otp_id = #{otpId}

UPDATE tb_member_otp
SET expires_at = #{now}, updated_at = CURRENT_TIMESTAMP
WHERE member_id = #{memberId} AND purpose = #{purpose}
  AND verified_at IS NULL AND expires_at > #{now}
